import numpy as np,json,pathlib
rng=np.random.default_rng(52);N=100000;q=rng.integers(0,256,(N,8));q[:,7]=q[:,2];rec=rng.integers(0,256,(N,4,8));rec[:,:,7]=rec[:,:,2];raw=rng.random((N,4));raw*=.9285/np.maximum(1,raw.sum(1))[:,None];cap=(255-rec)//4;ratios=np.divide(cap,q[:,None,:]*raw[:,:,None],out=np.ones((N,4,8)),where=q[:,None,:]*raw[:,:,None]>0);lam=np.minimum(1,ratios.min(2));fractions=raw*lam;prefix=np.cumsum(fractions,axis=1);xi=rng.random((N,1,1));cumulative=np.floor(q[:,None,:]*prefix[:,:,None]+xi);flux=np.diff(np.concatenate([np.zeros((N,1,8)),cumulative],axis=1),axis=1).astype(int);stay=q-flux.sum(1);assert (flux>=0).all() and (stay>=0).all();assert (flux<=cap).all();assert np.array_equal(flux[:,:,2],flux[:,:,7]);assert np.array_equal(stay[:,2],stay[:,7]);
# Continuous-uniform ensemble mean one small donor, formerlyfloorlocked.
q0=1;f=np.array([.16,.08,.02,.01]);xi=rng.random((1000000,1));cum=np.floor(q0*np.cumsum(f)[None,:]+xi);fl=np.diff(np.c_[np.zeros(len(xi)),cum],axis=1);err=fl.mean(0)-q0*f;assert (abs(err)<.001).all()
pathlib.Path('temp/wc-runs/overnight-next/systematic-integer-flux-audit/proof.json').write_text(json.dumps({'randomDonors':N,'positiveStayCapsPairPASS':True,'formerlyLockedDonorQ1ExpectedFlux':f.tolist(),'millionSampleMeanFlux':fl.mean(0).tolist(),'maxMeanError':float(abs(err).max()),'scope':'Float64 CPU continuousuniform xi; actualGLSL and deterministic finitehash ensemble unverified'},indent=2)+'\n')
